  {section==='Roster'&&<section className="panel live-panel"><div className="panel-heading"><div><span className="panel-kicker">{roster?.locked?'LOCKED ROSTER':roster?'MONTHLY ROSTER':'ROSTER NOT GENERATED'}</span><h2>{roster?.name||'Generate a roster to begin'}</h2></div></div>{rosterView==='calendar'?<div className="roster-calendar-grid">{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(day=><b className="roster-day-name" key={day}>{day}</b>)}{Array.from({length:new Date(selectedMonth.year,selectedMonth.month-1,1).getDay()},(_,index)=><div className="roster-day roster-day-empty" key={`empty-${index}`}/>)}{calendarDays.map(date=>{const key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;const items=rosterAssignments.filter(item=>String(item.date).slice(0,10)===key);return <div className="roster-day" key={key}><b>{date.getDate()}</b>{items.slice(0,3).map((item,index)=><span className={`roster-assignment ${item.kind==='weekly-off'?'off':''}`} title={`${data.employees?.find(person=>person.id===String(item.employeeId))?.name||'Employee'} · ${data.processes?.find(process=>process.id===String(item.processId))?.name||'Process'}`} key={`${item._id||item.id||index}`}>{data.employees?.find(person=>person.id===String(item.employeeId))?.name||'Employee'} · {item.shift||item.kind}</span>)}{items.length>3&&<small>+{items.length-3} more</small>}</div>})}</div>:<div className="table-wrap"><table><thead><tr><th>Date</th><th>Employee</th><th>Brand</th><th>Process</th><th>Shift</th><th>Kind</th><th>Locked</th></tr></thead><tbody>{rosterAssignments.map((item,index)=><tr key={item._id||item.id||index}><td>{String(item.date).slice(0,10)}</td><td>{data.employees?.find(person=>person.id===String(item.employeeId))?.name||item.employeeId}</td><td>{data.brands?.find(value=>value.id===String(item.brandId))?.name||item.brandId}</td><td>{data.processes?.find(value=>value.id===String(item.processId))?.name||item.processId}</td><td>{item.shift||'—'}</td><td>{item.kind}</td><td><button className="button-outline" disabled={roster.locked} onClick={()=>setModal({entity:"roster-assignment-edit",mode:"edit",item})}>Edit</button> <button className="button-outline" disabled={roster.locked} onClick={()=>patchAssignment(item,{locked:!item.locked})}>{item.locked?'Unlock':'Lock'}</button> <button className="button-outline" disabled={roster.locked} onClick={()=>removeAssignment(item)}>Remove</button></td></tr>)}</tbody></table>{!rosterAssignments.length&&<div className="empty-state">No assignments for the selected filters.</div>}</div>}</section>}
